      messageId:r.message_id,bodyExcerpt:r.body.slice(0,240),reactionActorAlias:r.alias||(r.actor==='local-human'?'사용자':r.actor),reactionActorProvider:r.provider||(r.actor==='local-human'?'human':null),reactionActorAvatar:r.avatar||null,reactionActorSessionId:r.actor.startsWith('session:')?r.actor.slice(8):null,membershipId:r.membership_id||null,leftAt:r.left_at||null,emoji:r.emoji,label:REACTION_MEANINGS[r.emoji]?.label||r.emoji,hint:REACTION_MEANINGS[r.emoji]?.hint||'',createdAt:r.created_at
