    const message={id:id(),room_id:decision.room_id,sender_session_id:decision.owner,provenance:'decision',body:decision.body,kind:'post',reply_to:null,request_key:'decision:'+decision.id,payload_hash:hashPayload({body:decision.body,kind:'post',replyTo:null,targets:[],expectedTurnId:null}),created_at:decision.created_at,sender_role:role,decision_id:decision.id};
